"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["41031"],{6197(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>c,contentTitle:()=>d,toc:()=>p,assets:()=>h});var n=JSON.parse('{"id":"nhcx/v1/api/other/endpoints/other-internal-v1-task-submit","title":"Task submit (internal variant) (adapter)","description":"Internal twin of /v1/task/submit on the taskhcxservice, operationId hcxTaskPostInternal, with the same JWEPayload Task body and 202 envelope.","source":"@site/docs/nhcx/v1/api/other/endpoints/other-internal-v1-task-submit.mdx","sourceDirName":"nhcx/v1/api/other/endpoints","slug":"/nhcx/v1/api/other/endpoints/other-internal-v1-task-submit","permalink":"/docs/pr-13/docs/nhcx/v1/api/other/endpoints/other-internal-v1-task-submit","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Task submit (internal variant) (adapter)","sidebar_label":"Task submit (internal variant) (adapter)","sidebar_class_name":"api-method api-method--post","description":"Internal twin of /v1/task/submit on the taskhcxservice, operationId hcxTaskPostInternal, with the same JWEPayload Task body and 202 envelope.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-other.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Error report (callback)","permalink":"/docs/pr-13/docs/nhcx/v1/api/other/endpoints/other-v1-error"},"next":{"title":"Task callback (internal variant) (adapter)","permalink":"/docs/pr-13/docs/nhcx/v1/api/other/endpoints/other-internal-v1-task-on-submit"}}'),i=a(62540),r=a(43023),o=a(44136),s=JSON.parse('{"id":"other_internal_v1_task_submit","module":"Other","moduleId":"other","kind":"operation","method":"POST","path":"/internal/v1/task/submit","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Task submit (internal variant) (adapter)","description":"Internal twin of /v1/task/submit on the taskhcxservice, operationId hcxTaskPostInternal, with the same JWEPayload Task body and 202 envelope.\\n\\n### Business purpose\\n\\nThe taskhcxservice is one of six NHCX services that publish each operation at both /v1/... and /internal/v1/... with identical descriptions and request bodies, differing only in the operationId suffix. This is the internal form of the provider\'s reprocess or cancel request: the structured appeal path for rejected or short-paid claims and the withdrawal path for unused pre-authorisations. The specifications document no behavioural difference from the public endpoint.\\n\\n### When to use\\n\\nSame circumstances as /v1/task/submit: a reprocess (Task.code reprocess, reasonCode claimrejected or partialpayment, workflow 18) after an adverse adjudication with new evidence, or a preauth cancellation (Task.code cancel with a cancellation reasonCode, workflow 122 or PC01). x-hcx-correlation_id carries the original claim or preauth correlation id. The specs do not say when the internal path applies; default to the public path unless onboarding guidance names this one.\\n\\n### Preconditions\\n\\n- As for the public endpoint: active provider with NPI facility code, Bearer token, payer certificate for JWE encryption.\\n- Body is a JWEPayload whose plaintext is the Task resource with basedOn referencing the original entity by the sender\'s reference id, Task.input with claimNumber and intimation number, and supporting evidence.\\n- Protected header with the original correlation id, fresh api_call_id, IST timestamp, workflow id and status request.initiated.\\n- Confirmation that the internal route is intended for your integration.\\n\\n### Postconditions\\n\\nReturns 202 Accepted with StatusSuccessResponse (entity_type task), or 400, 404 or 500 in the same envelope. The payer answers later on the task on_submit callback with a Task bundle wrapping a ClaimResponse: workflows 251 received, 252 approved, 253 rejected, 254 queried, PC02 cancellation accomplished. The decision is final within the workflow context. No additional behaviour is documented for the internal variant.\\n\\n### Common mistakes\\n\\n- Expecting the internal path to skip validation of basedOn, correlation id or status; it is documented as identical.\\n- Omitting Task.basedOn or minting a fresh correlation id.\\n- Cancelling a preauth not in submitted or approved state (PAYR-1252, PAYR-1253, PAYR-1257, PAYR-1258).\\n- Hard-coding the internal prefix without confirming the route; a 404 may be a host or prefix mismatch.\\n\\n### Best practices\\n\\n- Reuse the public endpoint\'s Task builder; make only the path prefix configurable.\\n- Link to the original entity in both basedOn and Task.input; use Task.description with reasonCode other.\\n- Fresh api_call_id per call, IST timestamps, request.initiated on the outbound header.\\n- Persist correlation id and workflow id for matching the callback; implement v1/error.\\n\\n### Related scenario\\n\\nA hospital integrator generating a client from the taskhcxservice Swagger sees hcxTaskPost and hcxTaskPostInternal with the same description. The team builds one reprocess-and-cancel module that posts to /v1/task/submit by default and can be switched to the internal path if NHCX onboarding requires it. When a surgeon changes the treatment plan after a preauth was approved, the module sends Task.code cancel with reasonCode treatmentplanchanged under the preauth\'s correlation id, receives 202, and later gets the cancellation confirmation on the task on_submit callback before a new preauth is raised.\\n\\n### Specification\\n\\nChapter [Cancel, reprocess and shortfall](/docs/nhcx/v1/reference/fhir/cancel-reprocess-and-shortfall) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"},{"name":"x-hcx-sender_code","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"1000004446@hcx","type":"string"},{"name":"x-hcx-recipient_code","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"1518@hcx","type":"string"},{"name":"x-hcx-api_call_id","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-request_id","required":false,"description":"One per originating request. The Open Protocol page marks it Mandatory; the Technical Specifications page marks it Optional. Optional on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-correlation_id","required":true,"description":"The thread. See the rule below. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-workflow_id","required":false,"description":"Which step, or which case. See the two readings below. Optional on the envelope.","example":"122","type":"string"},{"name":"x-hcx-timestamp","required":true,"description":"See the format note below. Mandatory on the envelope.","example":"<iso timestamp>","type":"string"},{"name":"x-hcx-status","required":true,"description":"Where this message stands. Values below. Mandatory on the envelope.","example":"request.initiated","type":"string"},{"name":"x-hcx-ben-abha-id","required":true,"description":"The beneficiary\'s ABHA number. Mandatory on every exchange, including those with no beneficiary in the payload. Mandatory on the envelope.","example":"91711234567890","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"payload","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"payload":"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag"},"responses":[{"status":"200","description":"Returns 202 Accepted with StatusSuccessResponse (entity_type task), or 400, 404 or 500 in the same envelope.","example":{"timestamp":"25/08/2026 10:20:00:093","api_call_id":"b4c5d6e7-f8a9-0123-7890-234567890123","correlation_id":"778899aa-bbcc-ddee-ff00-112233445566","result":{"sender_code":"1000004446@hcx","recipient_code":"1518@hcx","entity_type":"task","protocol_status":"request.queued"},"error":{"code":"","message":""}}}],"tag":"Adapter","tagDescription":"Internal twins of the exchange calls, for the NHCX adapter deployment.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/task/submit \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 122\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: request.initiated\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/task/submit \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 122\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: request.initiated\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/internal/v1/task/submit\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"x-hcx-sender_code\\": \\"1000004446@hcx\\",\\n        \\"x-hcx-recipient_code\\": \\"1518@hcx\\",\\n        \\"x-hcx-api_call_id\\": \\"<uuid>\\",\\n        \\"x-hcx-request_id\\": \\"<uuid>\\",\\n        \\"x-hcx-correlation_id\\": \\"<uuid>\\",\\n        \\"x-hcx-workflow_id\\": \\"122\\",\\n        \\"x-hcx-timestamp\\": \\"<iso timestamp>\\",\\n        \\"x-hcx-status\\": \\"request.initiated\\",\\n        \\"x-hcx-ben-abha-id\\": \\"91711234567890\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/internal/v1/task/submit\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"x-hcx-sender_code\\": \\"1000004446@hcx\\",\\n    \\"x-hcx-recipient_code\\": \\"1518@hcx\\",\\n    \\"x-hcx-api_call_id\\": \\"<uuid>\\",\\n    \\"x-hcx-request_id\\": \\"<uuid>\\",\\n    \\"x-hcx-correlation_id\\": \\"<uuid>\\",\\n    \\"x-hcx-workflow_id\\": \\"122\\",\\n    \\"x-hcx-timestamp\\": \\"<iso timestamp>\\",\\n    \\"x-hcx-status\\": \\"request.initiated\\",\\n    \\"x-hcx-ben-abha-id\\": \\"91711234567890\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Task submit (internal variant) (adapter)",sidebar_label:"Task submit (internal variant) (adapter)",sidebar_class_name:"api-method api-method--post",description:"Internal twin of /v1/task/submit on the taskhcxservice, operationId hcxTaskPostInternal, with the same JWEPayload Task body and 202 envelope.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-other.yaml",generated:!0},d,h={},p=[];function l(e){return(0,i.jsx)(o.A,{operation:s})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}}}]);